import heapq

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    pq = [(0, start)]
    while pq:
        cur_dist, cur = heapq.heappop(pq)
        if cur_dist > distances[cur]:
            continue
        for neighbor, weight in graph[cur]:
            dist = cur_dist + weight
            if dist < distances[neighbor]:
                distances[neighbor] = dist
                heapq.heappush(pq, (dist, neighbor))
    return distances

function dijkstra(graph, start) {
  const distances = {}
  for (const node in graph) distances[node] = Infinity
  distances[start] = 0
  const visited = new Set()
  while (true) {
    let cur = null
    for (const node in distances) {
      if (!visited.has(node) && (cur === null || distances[node] < distances[cur])) {
        cur = node
      }
    }
    if (cur === null || distances[cur] === Infinity) break
    visited.add(cur)
    for (const [neighbor, weight] of graph[cur]) {
      const dist = distances[cur] + weight
      if (dist < distances[neighbor]) distances[neighbor] = dist
    }
  }
  return distances
}
